async function imageFileToDataUrl(file,maxSide=1600){
 if(!file||!file.type?.startsWith('image/')) throw new Error('Please select an image file');
 const bitmap=await createImageBitmap(file);
 const scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
 const w=Math.max(1,Math.round(bitmap.width*scale)),h=Math.max(1,Math.round(bitmap.height*scale));
 const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
 const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,w,h);bitmap.close?.();
 let quality=.82;
 let data=canvas.toDataURL('image/webp',quality);
 while(data.length>1200000&&quality>.5){quality-=.08;data=canvas.toDataURL('image/webp',quality)}
 if(data.length>1200000){data=canvas.toDataURL('image/jpeg',.72)}
 if(data.length>1500000) throw new Error('Image is too large after compression. Choose a smaller image.');
 return data;
}
async function handleImageFile(file,onDone,onError){
 try{onDone(await imageFileToDataUrl(file))}
 catch(e){onError?.(e)}
}
